"use client";
import { useRouter } from "next/navigation";
import { useState } from "react";

export default function Form() {
  const [email, setEmail] = useState<string>("");
  const [pass, setPass] = useState<string>("");
  const [error, setError] = useState<string>("");
  const [isloading, setIslaoding] = useState<boolean>(false);
  const router = useRouter();
  const HandleSignUp = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setError("");
    setIslaoding(true);

    try {
      const res = await fetch("http://localhost:2017/auth/signup", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email: email, password: pass }),
      });
      const rest = await res.json();
      if (!res.ok) {
        const errormessage = Array.isArray(rest.message)
          ? rest.message.join(",")
          : rest.message || "signup failed";
        throw new Error(errormessage);
      }
      console.log(rest);
      localStorage.setItem("access_token", rest.access_token);
      localStorage.setItem("role_key", rest.user.role);
      router.push("/");
    } catch (error) {
      setError(error.message);
      console.log(error);
    } finally {
      setIslaoding(false);
    }
  };

  const HandleSignIn = async (e: React.MouseEvent<HTMLButtonElement>) => {
    e.preventDefault();
    setError("");
    setIslaoding(true);
    try {
      const res = await fetch("http://localhost:2017/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email: email, password: pass }),
      });
      const data = await res.json();
      if (!res.ok) {
        const errormessage = Array.isArray(data.message)
          ? data.message.join(",")
          : data.message || "signup failed";
        throw new Error(errormessage);
      }
      console.log(data.access_token, data.user.role);
      localStorage.setItem("access_token", data.access_token);
      localStorage.setItem("role_key", data.user.role);
      router.push("/protected");
    } catch (error) {
      setError(error.message);
      console.log(error);
    } finally {
      setIslaoding(false);
    }
  };

  return (
    <div className="flex justify-center">
      <div className="border-2 mt-[30%] rounded-md  w-1/2 border-pink-300 backdrop-filter backdrop-blur-xl">
        {error && <div className="bg-pink-300">{error}</div>}
        <form className="flex flex-col gap-1.5 px-2 py-4">
          <div className="flex gap-12">
            <label> email </label>
            <input
              type="text"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="rounded-md bg-pink-200 w-1/2 text-balck"
            />
          </div>
          <div className="flex gap-12">
            <label>Password</label>
            <input
              type="password"
              value={pass}
              onChange={(e) => setPass(e.target.value)}
              className="rounded-md bg-pink-200 w-1/2 text-black"
            />
          </div>

          <button
            className="bg-pink-300 text-white w-1/2"
            onClick={HandleSignUp}
          >
            {" "}
            Signup
          </button>
          <button
            className=" bg-white text-pink-500 w-1/2"
            onClick={HandleSignIn}
          >
            {" "}
            Signin
          </button>
        </form>
      </div>
    </div>
  );
}
